param(\n    [switch]$InstallDependencies\n)\n\n$ErrorActionPreference = \"Stop\"\n$PatchRoot = Split-Path -Parent $MyInvocation.MyCommand.Path\n$ProjectRoot = (Get-Location).Path\n\nif (-not (Test-Path (Join-Path $ProjectRoot \"pyproject.toml\"))) {\n    throw \"Execute este instalador a partir da raiz do projeto (onde existe pyproject.toml).\"\n}\n\nNew-Item -ItemType Directory -Force (Join-Path $ProjectRoot \"src\\iip\\harvest\") | Out-Null\nNew-Item -ItemType Directory -Force (Join-Path $ProjectRoot \"scripts\") | Out-Null\nNew-Item -ItemType Directory -Force (Join-Path $ProjectRoot \"tests\") | Out-Null\n\nCopy-Item -Force (Join-Path $PatchRoot \"src\\iip\\harvest\\__init__.py\") (Join-Path $ProjectRoot \"src\\iip\\harvest\\__init__.py\")\nCopy-Item -Force (Join-Path $PatchRoot \"src\\iip\\harvest\\patria.py\") (Join-Path $ProjectRoot \"src\\iip\\harvest\\patria.py\")\nCopy-Item -Force (Join-Path $PatchRoot \"scripts\\patria_harvester.py\") (Join-Path $ProjectRoot \"scripts\\patria_harvester.py\")\nCopy-Item -Force (Join-Path $PatchRoot \"tests\\test_patria_harvester.py\") (Join-Path $ProjectRoot \"tests\\test_patria_harvester.py\")\nCopy-Item -Force (Join-Path $PatchRoot \"requirements-patria-harvester.txt\") (Join-Path $ProjectRoot \"requirements-patria-harvester.txt\")\nCopy-Item -Force (Join-Path $PatchRoot \"README_PATCH.md\") (Join-Path $ProjectRoot \"README_PATCH.md\")\n\nWrite-Host \"Patch Patria instalado no projeto: $ProjectRoot\"\n\nif ($InstallDependencies) {\n    python -m pip install -r .\\requirements-patria-harvester.txt\n    python -m playwright install chromium\n}\n\nWrite-Host \"Teste: python -m pytest .\\tests\\test_patria_harvester.py -q\"\nWrite-Host \"Execução: python .\\scripts\\patria_harvester.py --ticker PCIP11 --years 2019-2026\"\n